def create_permission(apps, database, model, codename, label):
    # On a fresh database the post_migrate signal has not created permissions yet.
    content_type, _ = apps.get_model('contenttypes', 'ContentType').objects.using(database).get_or_create(
        app_label='core', model=model,
    )
    permission, _ = apps.get_model('auth', 'Permission').objects.using(database).get_or_create(
        content_type=content_type, codename=codename, defaults={'name': label},
    )
    return permission


def grant_permissions(apps, database, user, permissions):
    for model, actions in permissions.items():
        label = apps.get_model('core', model)._meta.verbose_name
        user.user_permissions.add(*[
            create_permission(apps, database, model, f'{action}_{model}', f'Can {action} {label}')
            for action in actions
        ])


def setup_provider(apps, database, provider):
    city, _ = apps.get_model('core', 'City').objects.using(database).get_or_create(name='Valparaíso')
    category, _ = apps.get_model('core', 'Category').objects.using(database).get_or_create(name='Deportes')
    center, created = apps.get_model('core', 'Organization').objects.using(database).get_or_create(
        origin_key='demo:operator-center',
        defaults={
            'name': 'Centro Kiddo Spark Demo', 'kind': 'provider', 'city': city, 'specialty': category,
            'email': provider.email, 'created_by': provider, 'approved': True,
            'description': 'Centro ficticio para probar la gestión de un proveedor.',
        },
    )
    if not created:
        return
    center.administrators.add(provider)
    activity = apps.get_model('core', 'Activity').objects.using(database).create(
        origin_key='demo:operator-activity', name='Taller de movimiento demo',
        organization=center, category=category, description='Actividad de prueba del centro demo.',
        age_min=5, age_max=14, sparks=4, price=0, active=True,
    )
    starts_at = (timezone.localtime() + timedelta(days=7)).replace(hour=17, minute=0, second=0, microsecond=0)
    apps.get_model('core', 'Schedule').objects.using(database).create(
        activity=activity, starts_at=starts_at, capacity=8, available=8,
    )


def create_local_accounts(apps, schema_editor):
    if not getattr(settings, 'KIDDO_SEED_DEMO_ACCOUNTS', False):
        return
    database = schema_editor.connection.alias
    users = apps.get_model('core', 'User').objects.using(database)
    demo_accounts = (
        ('superadmin', 'correo@superadmin.cl', 'Superadmin Demo', True, True),
        ('admin', 'admin@demo.example.invalid', 'Administrador Demo', True, False),
        ('usuario', 'usuario@demo.example.invalid', 'Familia Demo', False, False),
        ('proveedor', 'proveedor@demo.example.invalid', 'Proveedor Demo', True, False),
    )
    for username, email, name, is_staff, is_superuser in demo_accounts:
        # An older installation may already use the name or email. Preserve its accounts.
        if users.filter(username__iexact=username).exists() or users.filter(email__iexact=email).exists():
            continue
        user = users.create(
            username=username, email=email, first_name=name, password=make_password(username),
            is_active=True, is_staff=is_staff, is_superuser=is_superuser,
        )
        if username == 'admin':
            user.user_permissions.add(create_permission(
                apps, database, 'user', 'operate_platform', 'Puede operar el catálogo y las solicitudes de la plataforma',
            ))
            grant_permissions(apps, database, user, PLATFORM_PERMISSIONS)
        elif username == 'proveedor':
            grant_permissions(apps, database, user, PROVIDER_PERMISSIONS)
            setup_provider(apps, database, user)


